/**
 * SLATE — the high street: the shops most people actually buy from.
 *
 * Zara, H&M, COS, Mango, Gap, Massimo Dutti, Muji and Marks & Spencer.
 * Between them they dress most of the world most of the time, and until now
 * each had a shopfront with five things in it. A shop with a brand over the
 * door sells that brand and nothing else, so a thin brand is a thin shop.
 *
 * These companies do not name their clothes the way a house does. There is no
 * Baguette on a Zara rail; there is a poplin shirt, and next season another
 * one. So the pieces here are named the way the shop names them, and the
 * lines that are real lines — ZW Collection, Divided, H&M Studio, Per Una,
 * Autograph, Goodmove, GapFit, Limited Edition — are named because the
 * company really runs them.
 *
 * Public record: the company, the line, the fabric and the cut. SLATE's own
 * arithmetic: every price, every quality figure, every wear rate, labeled as
 * a calibration on the row.
 */

import { REFERENCE_VERSION } from './reference';
import { HOUSE_NOTE } from './labels';
import type { RealGood } from './goods';

const REAL = {
  source: 'calibrated_estimate', confidence: 'high', version: REFERENCE_VERSION,
  note: HOUSE_NOTE,
} as const;

const ALL_YEAR = ['Spring', 'Summer', 'Autumn', 'Winter'];
const WINTER = ['Autumn', 'Winter'];
const SUMMER = ['Spring', 'Summer'];

type Who = 'men' | 'women' | 'unisex';

const rw = (
  id: string, name: string, brand: string, sub: string, price: number,
  slot: string, formality: number, quality: number, who: Who = 'unisex',
  depreciation = 0.46, seasons: string[] = ALL_YEAR,
): RealGood => ({
  id, name, type: 'product', category: 'clothing', subcategory: sub, basePrice: price, brand,
  tags: ['wear', sub], quality, depreciation, slot, formality, seasons, audience: who, ...REAL,
});

const sh = (
  id: string, name: string, brand: string, sub: string, price: number,
  formality: number, quality: number, who: Who = 'unisex', depreciation = 0.44,
): RealGood => ({
  id, name, type: 'product', category: 'footwear', subcategory: sub, basePrice: price, brand,
  tags: ['wear', 'shoes', sub], quality, depreciation, slot: 'shoes', formality,
  seasons: ALL_YEAR, audience: who, ...REAL,
});

const ac = (
  id: string, name: string, brand: string, sub: string, price: number,
  slot: string | undefined, formality: number, quality: number, who: Who = 'unisex', depreciation = 0.40,
): RealGood => ({
  id, name, type: 'product', category: 'accessory', subcategory: sub, basePrice: price, brand,
  tags: ['wear', sub], quality, depreciation, slot, formality, seasons: ALL_YEAR,
  audience: who, ...REAL,
});

const gr = (
  id: string, name: string, brand: string, sub: string, price: number,
  shelf: number, unit: string, nourishment: number, quality = 62,
): RealGood => ({
  id, name, type: 'product', category: 'groceries', subcategory: sub, basePrice: price, brand,
  tags: ['grocery', sub], quality, depreciation: 0, shelfLifeDays: shelf, unit, nourishment,
  audience: 'unisex', ...REAL,
});

const hm = (
  id: string, name: string, brand: string, sub: string, price: number,
  quality: number, depreciation = 0.42,
): RealGood => ({
  id, name, type: 'product', category: 'home', subcategory: sub, basePrice: price, brand,
  tags: ['home', sub], quality, depreciation, seasons: ALL_YEAR, audience: 'unisex', ...REAL,
});

